import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.io.PrintWriter;import java.util.StringTokenizer;public class Main {    public static void main(String[] args) throws IOException {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        PrintWriter out = new PrintWriter(System.out);        StringTokenizer st;        int T = Integer.parseInt(br.readLine());        while (T-- > 0) {            int N = Integer.parseInt(br.readLine());            st = new StringTokenizer(br.readLine());            int[] A = new int[N];            for (int i = 0; i < N; i++) {                A[i] = Integer.parseInt(st.nextToken());            }            if (N == 1) {                out.println("YES");            } else {                if (A[0] != A[N - 1]) {                    out.println("NO");                } else {                    int target = A[0];                    boolean possible = true;                    for (int i = 0; i < N; i++) {                        if (A[i] < target) {                            possible = false;                            break;                        }                    }                    if (possible) {                        out.println("YES");                    } else {                        out.println("NO");                    }                }            }        }        out.flush();        out.close();    }}